Looking at the examples, I identify the rule:
1. Find the cell with value 4
2. Note its local position (r,c) within its 3×3 block — this determines which block position in the output receives content
3. Copy that block's content to the determined output block position; zero everything else (keep 5-separators)

```python
def solve(grid):
    rows, cols = len(grid), len(grid[0])

    # Find position of 4
    r4, c4 = None, None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 4:
                r4, c4 = r, c

    # Determine block boundaries (separated by 5-lines)
    row_groups = []
    col_groups = []
    rs, cs = [], []
    for r in range(rows):
        if all(grid[r][c] == 5 for c in range(cols)):
            if rs: row_groups.append(rs)
            rs = []
        else:
            rs.append(r)
    if rs: row_groups.append(rs)

    for c in range(cols):
        if all(grid[r][c] == 5 for r in range(rows)):
            if cs: col_groups.append(cs)
            cs = []
        else:
            cs.append(c)
    if cs: col_groups.append(cs)

    # Find which block contains 4 and local position
    src_br, src_bc = None, None
    local_r, local_c = None, None
    for bi, rg in enumerate(row_groups):
        for bj, cg in enumerate(col_groups):
            if r4 in rg and c4 in cg:
                src_br, src_bc = bi, bj
                local_r = rg.index(r4)
                local_c = cg.index(c4)

    # Destination block is (local_r, local_c)
    dst_br, dst_bc = local_r, local_c

    # Build output
    out = [[grid[r][c] if all(grid[r][cc] == 5 for cc in range(cols)) or all(grid[rr][c] == 5 for rr in range(rows)) else 0 for c in range(cols)] for r in range(rows)]

    src_rows = row_groups[src_br]
    src_cols = col_groups[src_bc]
    dst_rows = row_groups[dst_br]
    dst_cols = col_groups[dst_bc]

    for i in range(len(src_rows)):
        for j in range(len(src_cols)):
            out[dst_rows[i]][dst_cols[j]] = grid[src_rows[i]][src_cols[j]]

    return out
